import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private boolean hasNextByte() {
            if (ptr < len) return true;
            ptr = 0;
            try {
                len = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return len > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        if (n == -1) return;
        int k = sc.nextInt();
        int u = sc.nextInt();

        // Forward star / adjacency list representation for card numbers
        // Total occurrences = n * k
        int total = n * k;
        int[] head = new int[u + 1];
        java.util.Arrays.fill(head, -1);
        int[] to = new int[total];
        int[] next = new int[total];
        int edgeCount = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < k; j++) {
                int num = sc.nextInt();
                to[edgeCount] = i;
                next[edgeCount] = head[num];
                head[num] = edgeCount++;
            }
        }

        int[] remaining = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            remaining[i] = k;
        }

        List<Integer> winners = new ArrayList<>();
        boolean foundWinners = false;

        for (int step = 0; step < u; step++) {
            int drawn = sc.nextInt();
            if (!foundWinners) {
                for (int e = head[drawn]; e != -1; e = next[e]) {
                    int card = to[e];
                    remaining[card]--;
                    if (remaining[card] == 0) {
                        winners.add(card);
                    }
                }
                if (!winners.isEmpty()) {
                    foundWinners = true;
                }
            }
        }

        Collections.sort(winners);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < winners.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(winners.get(i));
        }
        System.out.println(sb);
    }
}
